/* Speculative Score Draft */
// The core is a single, processed vocal line. Use a MonoSynth with a fat oscillator for body.
// The main character comes from heavy reverb and slight detuning/chorus.

const reverb = new Tone.Reverb({ decay: 4, wet: 0.7 }).toDestination();
const chorus = new Tone.Chorus(0.2, 2.5, 0.5).connect(reverb);

const leadVocal = new Tone.MonoSynth({
  volume: -9,
  oscillator: { type: 'fatsawtooth', count: 3, spread: 20 },
  envelope: { attack: 0.02, decay: 0.2, sustain: 0.7, release: 0.5 },
  filterEnvelope: { attack: 0.01, decay: 0.1, sustain: 0.5, release: 0.8, baseFrequency: 300, octaves: 4 }
}).connect(chorus);

// Vocal phrases are syncopated and follow a D minor scale.
const vocalPart = new Tone.Sequence((time, note) => {
  if (note) leadVocal.triggerAttackRelease(note, '8n', time);
}, [
  'D4', 'D4', null, 'C4', 'A3', null, 'C4', null,
  'D4', 'D4', 'C4', 'A3', 'G3', null, null, null
], '8n').start(0);

Tone.Transport.bpm.value = 126;
